import {canonicalSha256} from '../core/canonical-json.mjs';
export function mineToolTracePatterns({traces=[]}={}){const byTask=new Map();for(const trace of traces){if(!byTask.has(trace.taskClass))byTask.set(trace.taskClass,[]);byTask.get(trace.taskClass).push(trace);}const out=[];for(const [taskClass,items] of byTask){const successes=items.filter(x=>x.success);if(successes.length<2)continue;const counts=new Map();for(const trace of successes){const sequence=[...new Set(trace.calls??[])].join('>');counts.set(sequence,(counts.get(sequence)??0)+1);}const best=[...counts].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))[0];const payload={kind:'tool-sequence',maturity:'observed',taskClass,sequence:best[0].split('>'),observations:items.length,successObservations:successes.length,medianTokens:[...successes].map(x=>x.tokens??0).sort((a,b)=>a-b)[Math.floor(successes.length/2)]};out.push(Object.freeze({...payload,instinctSha256:canonicalSha256(payload)}));}return out.sort((a,b)=>a.taskClass.localeCompare(b.taskClass));}
